AssistantMessageToolRequest(name='create', tool_call_id='function-call-3e846340-bb35-435a-b61e-fd0228a88c75', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('support-form');
    const statusMessage = document.getElementById('status-message');

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        // Reset status message
        statusMessage.textContent = '';
        statusMessage.className = '';

        // Clear any previous error messages
        const existingErrors = form.querySelectorAll('.error-message');
        existingErrors.forEach(error => error.remove());

        const inputs = form.querySelectorAll('input[required]');
        let firstInvalid = null;

        inputs.forEach(input => {
            input.removeAttribute('aria-invalid');
            if (!input.value.trim()) {
                if (!firstInvalid) firstInvalid = input;
                input.setAttribute('aria-invalid', 'true');

                // Although the prompt said "Do not show inline validation messages on initial render",
                // it's good practice to show them on submission failure.
                const error = document.createElement('p');
                error.className = 'error-message';
                error.textContent = `Error: ${input.previousElementSibling.textContent.replace(' *', '')} is required.`;
                input.after(error);

                // Link error message to input
                const errorId = `${input.id}-error`;
                error.id = errorId;
                const existingDescribedBy = input.getAttribute('aria-describedby') || '';
                input.setAttribute('aria-describedby', `${existingDescribedBy} ${errorId}`.trim());
            }
        });

        if (firstInvalid) {
            firstInvalid.focus();
            statusMessage.textContent = 'Please correct the errors before submitting.';
            statusMessage.style.color = 'var(--error-color)';
            return;
        }

        // Simulate successful submission
        statusMessage.textContent = 'Sending message...';
        statusMessage.style.color = 'var(--primary-color)';

        setTimeout(() => {
            statusMessage.textContent = 'Message sent successfully! We will contact you soon.';
            statusMessage.style.color = 'var(--secondary-color)';
            form.reset();
        }, 1500);
    });
});
