    --error-color: #cf6679;
    --on-bg-color: #e1e1e1;
    --on-surface-color: #ffffff;
    --input-bg: #2c2c2c;
    --input-border: #444444;
    --focus-outline: #bb86fc;
}

body {
    background-color: var(--bg-color);
    color: var(--on-bg-color);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.6;
    margin: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

main {
    width: 100%;
    max-width: 500px;
    padding: 2rem;
}

.contact-section {
    background-color: var(--surface-color);
    padding: 2.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

h1 {
    margin-top: 0;
    color: var(--on-surface-color);
    font-size: 1.75rem;
}

.form-field {
    margin-bottom: 1.5rem;
    display: flex;
    flex-direction: column;
}

label {
    margin-bottom: 0.5rem;
    font-weight: 500;
    color: var(--on-surface-color);
}

.required {
    color: var(--error-color);
    margin-left: 0.2rem;
}

input {
    background-color: var(--input-bg);
    border: 1px solid var(--input-border);
    border-radius: 4px;
    color: var(--on-surface-color);
    padding: 0.75rem;
    font-size: 1rem;
    transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
    outline: none;
    border-color: var(--focus-outline);
    box-shadow: 0 0 0 2px rgba(187, 134, 252, 0.4);
}

/* Ensure focus outline for keyboard users if outline is removed */
input:focus-visible {
    outline: 2px solid var(--focus-outline);
    outline-offset: 2px;
}

.helper-text {
    margin-top: 0.4rem;
    font-size: 0.85rem;
    color: #aaaaaa;
}

button {
    background-color: var(--primary-color);
    color: #000000;
    border: none;
    border-radius: 4px;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
    width: 100%;
}

button:hover {
    background-color: #d7b7fd;
}

button:active {
    transform: translateY(1px);
}

button:focus-visible {
    outline: 2px solid var(--on-surface-color);
    outline-offset: 4px;
}

#status-message {
    margin-top: 1.5rem;
    text-align: center;
    min-height: 1.5rem;
}

.error-message {
    color: var(--error-color);
    font-size: 0.9rem;
    margin-top: 0.25rem;
}
