+                input.after(error);
+                
+                // Link error message to input
+                const errorId = `${input.id}-error`;
+                error.id = errorId;
+                const existingDescribedBy = input.getAttribute('aria-describedby') || '';
+                input.setAttribute('aria-describedby', `${existingDescribedBy} ${errorId}`.trim());
+            }
+        });
+
+        if (firstInvalid) {
+            firstInvalid.focus();
+            statusMessage.textContent = 'Please correct the errors before submitting.';
+            statusMessage.style.color = 'var(--error-color)';
+            return;
